using System.Security.Cryptography;
using CsoKit.Application;
using CsoKit.Core.Formats.Cso;
using CsoKit.Tests.Fixtures;

namespace CsoKit.Tests.Formats.Containers;

public sealed class ContainerDecompressionTests
{
    private const string Sha16kTail = "6644648daa03af1a6564f21702c9ba2a42101956ce64d4c3cb9b5891def417c0";
    private const string ShaDaxTail = "f329b12eab98a0ae4054c7d716089a0a329f5e4db57b987fe57a7efaeb1a2ced";

    // Generated by Fixtures/Cso/make_cso_fixtures.py in maxcso's large-block layout:
    // the final partial block is zero-filled and compressed as a full block.
    public static TheoryData<string, long, string> FullSizeFinalBlockFixtures => new()
    {
        { "cso1-16k-tail.cso", (3 * 16384) + (5 * 2048), Sha16kTail },
        { "cso2-16k-tail.cso", (3 * 16384) + (5 * 2048), Sha16kTail },
        { "dax-tail.dax", (3 * 8192) + (3 * 2048), ShaDaxTail },
    };

    [Theory]
    [MemberData(nameof(FullSizeFinalBlockFixtures))]
    public void Decompress_FullSizeFinalBlock_ProducesOriginalIso(string fixture, long expectedSize, string expectedSha256)
    {
        string directory = CreateTempDirectory();
        string output = Path.Combine(directory, "game.iso");

        try
        {
            CsoDecompressResult result = new CsoDecompressor().Decompress(new(FixturePath(fixture), output, false));

            Assert.True(result.Success, $"{result.ErrorCode}: {result.ErrorMessage}");
            Assert.Equal((ulong)expectedSize, result.BytesWritten);
            Assert.Equal(expectedSha256, Sha256Of(output));
            Assert.Equal(["game.iso"], Directory.GetFiles(directory).Select(Path.GetFileName));
        }
        finally
        {
            Directory.Delete(directory, recursive: true);
        }
    }

    [Theory]
    [MemberData(nameof(FullSizeFinalBlockFixtures))]
    public void DeepVerify_FullSizeFinalBlock_ReportsNoCorruption(string fixture, long expectedSize, string expectedSha256)
    {
        CsoOperationResult result = CsoOperationService.Verify(FixturePath(fixture), true, true, null);

        Assert.True(result.Success, result.Details);
        CsoVerifyOperationData data = Assert.IsType<CsoVerifyOperationData>(result.Data);
        Assert.Equal((ulong)expectedSize, data.BytesReconstructed);
        Assert.Equal(expectedSha256, data.Sha256, ignoreCase: true);
    }

    [Theory]
    [InlineData("cso2-lz4")]
    [InlineData("cso2-deflate")]
    [InlineData("dax")]
    [InlineData("dax-non-compressed-area")]
    public void Decompress_Cso2AndDax_RoundTripLogicalBytes(string kind)
    {
        byte[] logical = ContainerFixtures.DeterministicBytes(6 * 8192);
        string input = kind switch
        {
            "cso2-lz4" => ContainerFixtures.CreateCso2Lz4(logical),
            "cso2-deflate" => ContainerFixtures.CreateCso2Deflate(logical),
            "dax" => ContainerFixtures.CreateDaxCompressed(logical),
            _ => ContainerFixtures.CreateDaxWithNonCompressedArea(logical),
        };
        string directory = CreateTempDirectory();
        string output = Path.Combine(directory, "game.iso");

        try
        {
            CsoDecompressResult result = new CsoDecompressor().Decompress(new(input, output, false));

            Assert.True(result.Success, $"{result.ErrorCode}: {result.ErrorMessage}");
            Assert.Equal(logical, File.ReadAllBytes(output));
        }
        finally
        {
            File.Delete(input);
            Directory.Delete(directory, recursive: true);
        }
    }

    [Fact]
    public void Decompress_Cso2WithDataAfterLastBlock_FailsWithoutOutput()
    {
        string directory = CreateTempDirectory();
        string input = Path.Combine(directory, "input.cso");
        string output = Path.Combine(directory, "game.iso");
        File.WriteAllBytes(input, [.. File.ReadAllBytes(FixturePath("cso2-16k-tail.cso")), .. new byte[4]]);

        try
        {
            CsoDecompressResult result = new CsoDecompressor().Decompress(new(input, output, false));

            Assert.False(result.Success);
            Assert.Equal("InvalidCompressedData", result.ErrorCode);
            Assert.Contains("CSO2", result.ErrorMessage, StringComparison.Ordinal);
            Assert.Equal(["input.cso"], Directory.GetFiles(directory).Select(Path.GetFileName));
        }
        finally
        {
            Directory.Delete(directory, recursive: true);
        }
    }

    private static string FixturePath(string name)
    {
        return Path.Combine(AppContext.BaseDirectory, "Fixtures", "Cso", name);
    }

    private static string Sha256Of(string path)
    {
        using FileStream stream = File.OpenRead(path);
        return Convert.ToHexStringLower(SHA256.HashData(stream));
    }

    private static string CreateTempDirectory()
    {
        string directory = Path.Combine(Path.GetTempPath(), $"csokit-dec-{Guid.NewGuid():N}");
        Directory.CreateDirectory(directory);
        return directory;
    }
}
